@Injectable()
export class SecureActionGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}
  canActivate(ctx: ExecutionContext): boolean {
    const req = ctx.switchToHttp().getRequest();
    const roles = this.reflector.get<string[]>(Roles, ctx.getHandler()) ?? [];
    if (!req.user || !roles.every((r) => req.user.roles.includes(r))) throw new ForbiddenException();
    auditService.record(req.user, ctx.getHandler().name);
    return true;
  }
}

